  "hypothesis": "Replacing the single extremely sharp repair objective with a warm-started smoothing continuation will improve the best verified score by at least 1e-5 by allowing larger coordinated packet-weight adjustments.",
  "rationale": "The existing repair starts immediately at beta = 3e8, where competing convolution peaks create a poorly conditioned objective, and recent gains have been negligible. A short coarse-to-fine continuation preserves the topology search while letting repair redistribute packet mass before resolving the sharp maximum; exact verification still protects the incumbent.",
  "source": "import time
import numpy as np
import scipy.fft as fft
from scipy.signal import oaconvolve
from scipy.optimize import minimize

PARAMS = {
    'search_fraction': (0.43, 0.15, 0.55),
    'total_fraction': (0.70, 0.50, 0.73),
    'repair_tolerance': (0.0003, 0.000001, 0.01, 'log'),
    'beta': (3e8, 1e6, 1e11, 'log'),
    'cuts': (36, 12, 120),
    'initial_beta': (30000.0, 1000.0, 1000000.0, 'log'),
}


def decode(obj):
    if 'values' in obj:
        return np.maximum(np.asarray(obj['values'], dtype=float), 0.0)
    a = np.maximum(np.asarray(obj['ring'], dtype=float), 0.0)
    k = int(obj.get('cut', 0))
    mode = int(obj.get('reflection', 0))
    if mode == 1:
        return np.concatenate((a[:k][::-1], a[k:]))
    if mode == 2:
        return np.concatenate((a[:k], a[k:][::-1]))
    return np.concatenate((a[k:], a[:k])) if k else a.copy()


def exact_score(f):
    c = oaconvolve(f, f, mode='full')
    x = np.linspace(-0.5, 0.5, len(c) + 2)
    y = np.concatenate(([0.0], c, [0.0]))
    a, b = y[:-1], y[1:]
    num = float(np.sum((np.diff(x) / 3.0) * (a*a + a*b + b*b)))
    return float(num / ((np.sum(np.abs(c)) / (len(c)+1)) * np.max(np.abs(c))))


def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + float(params['total_fraction']) * budget_s
    search_end = start + float(params['search_fraction']) * budget_s
    if init is None:
        return {'values': [1.0]}
    f0 = decode(init)
    baseline = exact_score(f0)
    n = len(f0)
    if n < 4 or time.monotonic() >= deadline:
        return init
    rng = np.random.default_rng(seed)
    f0 = f0 / float(f0.max())
    m = fft.next_fast_len(2*n-1, real=True)
    best_score = baseline
    best_f = None
    contender = None
    contender_score = -np.inf

    def approximate(f):
        s = fft.rfft(f, m)
        c = fft.irfft(s*s, m)[:2*n-1]
        return float((2*np.dot(c, c) + np.dot(c[:-1], c[1:])) /
                     (3*np.sum(np.abs(c))*np.max(np.abs(c))))

    def make(k, mode):
        if mode == 0:
            return np.concatenate((f0[k:], f0[:k]))
        if mode == 1:
            return np.concatenate((f0[:k][::-1], f0[k:]))
        return np.concatenate((f0[:k], f0[k:][::-1]))

    def inspect(k, mode):
        nonlocal best_score, best_f, contender, contender_score
        if time.monotonic() >= search_end:
            return
        f = make(k, mode)
        score = approximate(f)
        if score > contender_score:
            contender_score = score
            contender = f
        if score > best_score - 2e-13 and time.monotonic() < deadline - 1.0:
            actual = exact_score(f)
            if actual > best_score:
                best_score = actual
                best_f = f.copy()

    cuts = set()
    cumulative = np.cumsum(f0)
    for q in np.linspace(0.01, 0.99, int(params['cuts'])):
        if time.monotonic() >= search_end:
            break
        cuts.add(int(np.searchsorted(cumulative, q*cumulative[-1])))
    for d in np.geomspace(1, max(2, n//3), 18):
        if time.monotonic() >= search_end:
            break
        cuts.add(int(d))
        cuts.add(n-int(d))
    occupied = f0 > 0
    changes = np.flatnonzero(occupied[1:] != occupied[:-1]) + 1
    edges = np.r_[0, changes, n]
    widths = np.diff(edges)
    for j in np.argsort(widths)[::-1][:24]:
        if time.monotonic() >= search_end:
            break
        if not occupied[edges[j]]:
            cuts.add(int((edges[j]+edges[j+1])//2))
            cuts.add(int(edges[j]))
            cuts.add(int(edges[j+1]))
    cuts = [k for k in sorted(cuts) if 0 < k < n]
    rng.shuffle(cuts)
    jobs = [(k, mode) for k in cuts for mode in (0, 1, 2)]
    rng.shuffle(jobs)
    for k, mode in jobs:
        if time.monotonic() >= search_end:
            break
        inspect(k, mode)

    def result():
        if best_f is None:
            return init
        return {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}

    if contender is None or contender_score < baseline - float(params['repair_tolerance']):
        return result()
    if time.monotonic() >= deadline - 1.5:
        return result()

    base = contender
    spec = fft.rfft(base, m)
    peak = fft.irfft(spec*spec, m)[:2*n-1].max()
    base = base / np.sqrt(peak)
    indices = np.flatnonzero(base > 0)
    starts = np.r_[True, (np.diff(indices) != 1) | (indices[1:]//256 != indices[:-1]//256)]
    labels = np.cumsum(starts, dtype=np.int64)-1
    groups = int(labels[-1])+1
    active = base[indices]
    beta = float(params['initial_beta'])
    stage_end = deadline - 1.2

    class Stop(Exception):
        pass

    def materialize(x):
        f = np.zeros(n)
        f[indices] = active*np.square(x[labels])
        return f

    def objective(x):
        nonlocal best_score, best_f
        if time.monotonic() >= min(stage_end, deadline-1.2):
            raise Stop()
        f = materialize(x)
        sp = fft.rfft(f, m)
        c = fft.irfft(sp*sp, m)[:2*n-1]
        peak = c.max()
        e = np.exp(beta*(c-peak))
        z = e.sum()
        smooth = peak + np.log(z)/beta
        num = (2*np.dot(c,c)+np.dot(c[:-1],c[1:]))/3
        total = f.sum()
        quick = num/(np.sum(np.abs(c))*np.max(np.abs(c)))
        if quick > best_score + 1e-13 and time.monotonic() < deadline-1.0:
            actual = exact_score(f)
            if actual > best_score:
                best_score = actual
                best_f = f.copy()
        g = 4*c
        g[1:] += c[:-1]
        g[:-1] += c[1:]
        g /= 3*num
        g -= e/(z*smooth)
        corr = fft.irfft(fft.rfft(g,m)*np.conj(sp),m)[:n]
        local = (2*corr[indices]-2/total)*active
        grad = 2*x*np.bincount(labels,weights=local,minlength=groups)
        value = np.log(num)-2*np.log(total)-np.log(smooth)
        return -value, -grad

    # Carry accepted iterates, but restart curvature information as smoothing changes.
    # Early stages receive only a small fraction of the remaining repair time.
    x = np.ones(groups)
    repair_start = time.monotonic()
    available = max(0.0, deadline - 1.5 - repair_start)
    schedule = [float(params['initial_beta']),
                np.sqrt(float(params['initial_beta'])*float(params['beta'])),
                float(params['beta'])]
    fractions = [0.18, 0.42, 1.0]
    accepted_x = x.copy()

    def callback(current):
        nonlocal accepted_x
        accepted_x = current.copy()
        if time.monotonic() >= min(stage_end, deadline-1.2):
            raise Stop()

    for j, beta_value in enumerate(schedule):
        if time.monotonic() >= deadline - 1.5:
            break
        beta = beta_value
        stage_end = repair_start + available*fractions[j]
        accepted_x = x.copy()
        try:
            opt = minimize(objective, x, jac=True, method='L-BFGS-B',
                           callback=callback,
                           options={'maxcor': 7, 'maxiter': 10000,
                                    'maxfun': 20000, 'ftol': 0.0,
                                    'gtol': 0.0, 'maxls': 15})
            x = opt.x.copy()
        except Stop:
            x = accepted_x.copy()
        # Normalize the iterate so beta has the same meaning at every stage.
        if time.monotonic() < deadline - 2.0:
            trial = materialize(x)
            sp = fft.rfft(trial, m)
            p = float(fft.irfft(sp*sp, m)[:2*n-1].max())
            if p > 0 and np.isfinite(p):
                x /= p**0.25
    return result()
